import assert from 'node:assert/strict';
import {createEnterpriseAdapter} from '../../../adapters/w03-enterprise.js';
import {composeEnterpriseSurface} from '../../../surfaces/enterprise/index.js';
const surface=composeEnterpriseSurface({relationAdapter:createEnterpriseAdapter()});
assert.equal(surface.contract.id,'enterprise');assert.equal(surface.domain.inspect().persistence.status,'UNAVAILABLE');
assert.equal(surface.bus.execute('enterprise.inspect').owner,'W03EnterpriseDomain');
const revision=surface.bus.execute('enterprise.revise',{expectedVersion:1});assert.equal(revision.snapshot.dirty,true);
surface.domain.setTwinBinding({baselineStatus:'STALE'});const before=surface.domain.receipts.length;const blocked=surface.bus.execute('enterprise.handoff');assert.equal(blocked.ok,false);assert.equal(blocked.code,'BASELINE_STALE');assert.equal(surface.domain.receipts.length,before);
const relBefore=surface.domain.relations.project().length;assert.throws(()=>surface.domain.edit({source:'SIM-ATK-01',target:'APP-WEB-01',type:'CONNECTS_TO',direction:'directed',sourcePin:'bogus',targetPin:'APP-WEB-01:eth0'}));assert.equal(surface.domain.relations.project().length,relBefore);
assert.equal(surface.platformTruth.osAlwaysOnTop,'UNAVAILABLE');console.log('enterprise surface: PASS');
